// ============================================
// EXTRACT STUDENT DETAILS FROM TELEGRAM
// Supports:
// Name: Arjun
// Subjects: Physics, Chemistry
// Weak Subject: Chemistry
// etc.
// ============================================

const message = $json.message?.text || "";
const telegramUser = $json.message?.from || {};

const telegramId = telegramUser.id || "";
const telegramUsername = telegramUser.username || "";
const telegramFirstName = telegramUser.first_name || "";


// ============================================
// GET FIELD VALUE
// ============================================

function getField(label) {

  const regex = new RegExp(
    "^" + label + "\\s*:\\s*(.+)$",
    "im"
  );

  const match = message.match(regex);

  return match ? match[1].trim() : "";
}


// ============================================
// EXTRACT
// ============================================

const name = getField("Name");

const subjects = getField("Subjects");

const weakSubject = getField("Weak Subject");

const goal = getField("Goal");

const examDate = getField("Exam Date");

const dailyStudyHours = getField("Daily Study Hours");

const studyDays = getField("Study Days");

const preferredStudyTime = getField("Preferred Study Time");


// ============================================
// OUTPUT
// ============================================

return {
  json: {

    student_id: String(telegramId),

    telegram_id: telegramId,

    telegram_username: telegramUsername,

    telegram_first_name: telegramFirstName,

    name: name || telegramFirstName || "Student",

    subjects: subjects || "Not specified",

    weak_subject: weakSubject || "Not specified",

    goal: goal || "Not specified",

    exam_date: examDate || "Not specified",

    daily_study_hours: dailyStudyHours || "Not specified",

    study_days: studyDays || "Not specified",

    preferred_study_time: preferredStudyTime || "Not specified",

    original_message: message,

    extracted_at: new Date().toISOString()

  }
};

// ============================================
// AI STUDY PLAN → SIMPLE HTML
// ============================================

const plan =
  $json.output ||
  $json.text ||
  $json.response ||
  "";


// Get student data
const student = $("Extract Student Details").first().json;

const name = student.name || "Student";
const subjects = student.subjects || "Not specified";
const weakSubject = student.weak_subject || "Not specified";
const goal = student.goal || "Not specified";
const examDate = student.exam_date || "Not specified";
const dailyHours = student.daily_study_hours || "Not specified";
const studyDays = student.study_days || "Not specified";
const preferredTime = student.preferred_study_time || "Not specified";


// ============================================
// ESCAPE HTML
// ============================================

function escapeHTML(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}


// ============================================
// SIMPLE MARKDOWN → HTML
// ============================================

function markdownToHTML(text) {

  let html = escapeHTML(text);

  // Headings
  html = html.replace(
    /^### (.*?)$/gm,
    "<h3>$1</h3>"
  );

  html = html.replace(
    /^## (.*?)$/gm,
    "<h2>$1</h2>"
  );

  html = html.replace(
    /^# (.*?)$/gm,
    "<h1>$1</h1>"
  );

  // Bold
  html = html.replace(
    /\*\*(.*?)\*\*/g,
    "<strong>$1</strong>"
  );

  // Bullet points
  html = html.replace(
    /^[•*-] (.*?)$/gm,
    "<li>$1</li>"
  );

  // Group consecutive li elements
  html = html.replace(
    /(<li>.*?<\/li>\s*)+/gs,
    match => `<ul>${match}</ul>`
  );

  // Numbered lists
  html = html.replace(
    /^\d+\.\s+(.*?)$/gm,
    "<li>$1</li>"
  );

  // Tables
  const lines = html.split("\n");
  const output = [];

  let inTable = false;

  for (let line of lines) {

    const trimmed = line.trim();

    if (trimmed.startsWith("|") && trimmed.endsWith("|")) {

      if (!inTable) {
        output.push("<table>");
        inTable = true;
      }

      // Skip Markdown separator row
      if (/^\|[\s|:-]+\|$/.test(trimmed)) {
        continue;
      }

      const cells = trimmed
        .slice(1, -1)
        .split("|")
        .map(cell => cell.trim());

      const tag =
        output[output.length - 1] === "<table>"
          ? "th"
          : "td";

      output.push(
        `<tr>${cells.map(c => `<${tag}>${c}</${tag}>`).join("")}</tr>`
      );

    } else {

      if (inTable) {
        output.push("</table>");
        inTable = false;
      }

      if (trimmed !== "") {
        output.push(trimmed);
      }
    }
  }

  if (inTable) {
    output.push("</table>");
  }

  html = output.join("\n");

  // Paragraph breaks
  html = html.replace(
    /\n{2,}/g,
    "</p><p>"
  );

  html = `<p>${html}</p>`;

  // Remove paragraph tags around block elements
  html = html.replace(/<p>(<h[123]>)/g, "$1");
  html = html.replace(/(<\/h[123]>)<\/p>/g, "$1");

  html = html.replace(/<p>(<ul>)/g, "$1");
  html = html.replace(/(<\/ul>)<\/p>/g, "$1");

  html = html.replace(/<p>(<table>)/g, "$1");
  html = html.replace(/(<\/table>)<\/p>/g, "$1");

  return html;
}


const formattedPlan = markdownToHTML(plan);


// ============================================
// SAFE FILE NAME
// ============================================

const safeName = name
  .replace(/[^a-zA-Z0-9-_ ]/g, "")
  .trim()
  .replace(/\s+/g, "_");


// ============================================
// FINAL HTML
// ============================================

const html = `
<!DOCTYPE html>

<html>
<head>

<meta charset="UTF-8">

<meta name="viewport"
content="width=device-width, initial-scale=1.0">

<title>AI Study Plan - ${escapeHTML(name)}</title>

<style>

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 30px 15px;
  background: #f1f5f9;
  font-family: Arial, sans-serif;
  color: #1e293b;
  line-height: 1.6;
}

.container {
  max-width: 900px;
  margin: auto;
  background: white;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0,0,0,.10);
}

.header {
  padding: 40px;
  background: linear-gradient(
    135deg,
    #312e81,
    #4f46e5
  );
  color: white;
}

.header h1 {
  margin: 0;
  font-size: 32px;
}

.header p {
  margin: 8px 0 0;
  opacity: .9;
}

.info {
  padding: 25px;
  background: #f8fafc;
}

.grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.card {
  padding: 14px;
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
}

.label {
  font-size: 10px;
  color: #64748b;
  text-transform: uppercase;
  font-weight: bold;
}

.value {
  margin-top: 4px;
  font-weight: bold;
}

.content {
  padding: 30px 40px;
}

h1 {
  color: #312e81;
}

h2 {
  margin-top: 28px;
  padding: 10px 14px;
  background: #eef2ff;
  border-left: 4px solid #4f46e5;
  border-radius: 6px;
  color: #312e81;
}

h3 {
  color: #4338ca;
}

p {
  margin: 10px 0;
}

ul {
  padding-left: 25px;
}

li {
  margin: 6px 0;
}

table {
  width: 100%;
  border-collapse: collapse;
  margin: 18px 0;
  font-size: 13px;
}

th {
  background: #312e81;
  color: white;
  padding: 10px;
  text-align: left;
}

td {
  padding: 10px;
  border: 1px solid #e2e8f0;
  vertical-align: top;
}

tr:nth-child(even) {
  background: #f8fafc;
}

.footer {
  padding: 18px;
  text-align: center;
  background: #f8fafc;
  color: #64748b;
  font-size: 11px;
}

@media(max-width:650px) {

  body {
    padding: 0;
  }

  .container {
    border-radius: 0;
  }

  .header {
    padding: 28px 22px;
  }

  .header h1 {
    font-size: 26px;
  }

  .content {
    padding: 25px 20px;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  table {
    font-size: 12px;
  }
}

</style>

</head>

<body>

<div class="container">

  <div class="header">

    <h1>📚 AI Study Planner</h1>

    <p>
      Personalized study plan for
      <strong>${escapeHTML(name)}</strong>
    </p>

  </div>


  <div class="info">

    <div class="grid">

      <div class="card">
        <div class="label">Student</div>
        <div class="value">
          ${escapeHTML(name)}
        </div>
      </div>

      <div class="card">
        <div class="label">Exam Date</div>
        <div class="value">
          ${escapeHTML(examDate)}
        </div>
      </div>

      <div class="card">
        <div class="label">Goal</div>
        <div class="value">
          ${escapeHTML(goal)}
        </div>
      </div>

      <div class="card">
        <div class="label">Daily Hours</div>
        <div class="value">
          ${escapeHTML(dailyHours)}
        </div>
      </div>

      <div class="card">
        <div class="label">Subjects</div>
        <div class="value">
          ${escapeHTML(subjects)}
        </div>
      </div>

      <div class="card">
        <div class="label">Weak Subject</div>
        <div class="value">
          ${escapeHTML(weakSubject)}
        </div>
      </div>

      <div class="card">
        <div class="label">Study Days</div>
        <div class="value">
          ${escapeHTML(studyDays)}
        </div>
      </div>

      <div class="card">
        <div class="label">Preferred Time</div>
        <div class="value">
          ${escapeHTML(preferredTime)}
        </div>
      </div>

    </div>

  </div>


  <div class="content">

    ${formattedPlan}

  </div>


  <div class="footer">

    <strong>AI Study Planner</strong>
    <br>
    Personalized • Practical • Actionable

  </div>

</div>

</body>
</html>
`;


// ============================================
// OUTPUT
// ============================================

return {
  json: {
    name,
    exam_date: examDate,
    goal,
    html,
    filename:
      `AI_Study_Plan_${safeName || "Student"}.html`
  }
};
